"""Teacher-model API adapter.

Install the optional runtime dependency with ``pip install openai`` and set
``ds_api_key`` before starting a live run.
"""

from __future__ import annotations

import json
import os
import re
from collections.abc import Mapping
from typing import Any
import config.config as cfg


def _parse_json_object(content: Any) -> dict[str, Any]:
    if isinstance(content, Mapping):
        return dict(content)
    if not isinstance(content, str) or not content.strip():
        raise ValueError("model returned empty content")

    text = content.strip()
    fenced = re.search(r"```(?:json)?\s*(.*?)\s*```", text, re.DOTALL | re.IGNORECASE)
    candidates = [fenced.group(1)] if fenced else []
    candidates.append(text)
    decoder = json.JSONDecoder()
    for candidate in candidates:
        try:
            parsed = json.loads(candidate)
            if isinstance(parsed, dict):
                return parsed
        except json.JSONDecodeError:
            for index, character in enumerate(candidate):
                if character != "{":
                    continue
                try:
                    parsed, _ = decoder.raw_decode(candidate, index)
                except json.JSONDecodeError:
                    continue
                if isinstance(parsed, dict):
                    return parsed
    raise ValueError("model content does not contain a valid JSON object")


def request_model_standard(messages: list[dict[str, str]]) -> dict[str, Any]:
    """Call the teacher model and return its structured JSON object."""
    api_key = cfg.ds_api_key
    if not api_key:
        raise RuntimeError("environment variable ds_api_key is not set")

    try:
        from openai import OpenAI
    except ImportError as exc:
        raise RuntimeError("openai is required: pip install openai") from exc

    client = OpenAI(
        api_key=api_key,
        base_url=os.environ.get("DS_BASE_URL", "https://api.deepseek.com"),
    )
    response = client.chat.completions.create(
        model=os.environ.get("DS_MODEL", "deepseek-v4-flash"),
        messages=messages,
        stream=False,
        reasoning_effort="low",
        extra_body={"thinking": {"type": "enabled"}},
    )

    print("=" * 30 + " model req_messages start " + "=" * 30)
    print(messages)
    print("=" * 30 + " model req_messages end " + "=" * 30)

    print("=" * 30 + " model raw response start " + "=" * 30)
    print(response.choices[0].message.content)
    print("=" * 30 + " model raw response end " + "=" * 30)

    return _parse_json_object(response.choices[0].message.content)


def request_model_stream(messages: list[dict[str, str]]) -> dict[str, Any]:
    """Stream the teacher-model response and return the parsed JSON object."""
    api_key = cfg.ds_api_key
    if not api_key:
        raise RuntimeError("environment variable ds_api_key is not set")

    try:
        from openai import OpenAI
    except ImportError as exc:
        raise RuntimeError("openai is required: pip install openai") from exc

    client = OpenAI(
        api_key=api_key,
        base_url=os.environ.get("DS_BASE_URL", "https://api.deepseek.com"),
    )

    print("=" * 30 + " model req_messages start " + "=" * 30)
    print(messages)
    print("=" * 30 + " model req_messages end " + "=" * 30)

    response_stream = client.chat.completions.create(
        model=os.environ.get("DS_MODEL", "deepseek-v4-flash"),
        messages=messages,
        stream=True,
        response_format={"type": "json_object"},
        reasoning_effort="high",
        extra_body={"thinking": {"type": "enabled"}},
    )

    content_parts: list[str] = []
    print("=" * 30 + " model raw response start " + "=" * 30)
    for chunk in response_stream:
        if not chunk.choices:
            continue
        content = chunk.choices[0].delta.content
        if not content:
            continue
        content_parts.append(content)
        print(content, end="", flush=True)
    print()
    print("=" * 30 + " model raw response end " + "=" * 30)

    return _parse_json_object("".join(content_parts))

def request_model(messages: list[dict[str, str]], stream: bool = True) -> dict[str, Any]:
    """Stream the teacher-model response and return the parsed JSON object."""
    if stream:
        return request_model_stream(messages)
    else:
        return request_model_standard(messages)



